        pub struct PrlSegment {
            pub sequence: u8,
            pub items: Vec<u8>,
        }
        impl PrlSegment {
            pub fn encode_to(&self, writer: &mut TlvWriter) -> Result<(), Error> {
                writer.write_u16(
                    u16::try_from((self.items).len()).map_err(|_| Error::TooLong)?,
                    Endian::Little,
                );
                writer.write_u8(self.sequence);
                for item in &self.items {
                    writer.write_u8(*item);
                }
                Ok(())
            }
            pub fn decode_from(reader: &mut TlvReader<'_>) -> Result<Self, Error> {
                let count = reader.read_u16(Endian::Little)? as usize;
                let sequence = reader.read_u8()?;
                let mut items = Vec::with_capacity(count.min(256));
                for _ in 0..count {
                    items.push(reader.read_u8()?);
                }
                Ok(Self { sequence, items })
            }
        }
